I'll implement the solution to create quick chats with project selection. Here's my approach:

1. Create a new `QuickChatSelector.vue` component that wraps ProjectDetailt
2. Modify `QuickBar.vue` to open the selector instead of directly creating a chat
3. Update `chat.js` to accept a project parameter when creating quick chats
4. Update `chats.js` store to pass the project_id when creating new chats

Let me implement this:

```vue src/components/QuickChatSelector.vue
<script setup>
import ProjectDetailt from './ProjectDetailt.vue'
</script>

<template>
  <div class="dropdown dropdown-end">
    <button 
      class="btn btn-sm btn-ghost gap-2 hover:bg-base-200"
      tabindex="0"
    >
      <i class="fa-solid fa-comments"></i>
      <span>Select Project</span>
    </button>
    <div 
      tabindex="0" 
      class="dropdown-content z-50 menu p-2 shadow bg-base-100 rounded-lg border border-white/40 w-56"
    >
      <ProjectDetailt 
        :model-value="selectedProject"
        @select="onProjectSelected"
        :options="{ showIcon: true, showFolders: false }"
        position="dropdown-end"
      />
    </div>
  </div>
</template>

<script>
export default {
  data() {
    return {
      selectedProject: null
    }
  },
  methods: {
    async onProjectSelected(project) {
      if (project) {
        await this.$service.chat.newQuickChat({ project })
        // Close the dropdown
        const dropdown = this.$el.querySelector('[tabindex="0"]')
        if (dropdown?.blur) dropdown.blur()
      }
    }
  }
}
</script>
