import moment from 'moment'
import Service from "./service"
import { extractCodeBlocks, hasCodeBlocksWithPaths } from '../utils/codeBlockExtractor'

export class ChatService extends Service {
  getUserMessage({ message, files, profiles, images, metadata, user, taskItem, task_item }) {
    return {
      role: "user",
      content: message,
      images: images?.map(JSON.stringify) || [],
      files,
      profiles,
      task_item: taskItem,
      user: user || this.$user.username,
      meta_data: metadata,
      done: true,
      task_item,
    }
  }

  async sendMessage({ chat, message }) {
    this.addMessage({ chat, message })
    return this.$projects.chatWihProject(chat)
  }

  async findChat({ id, owner_project_id } = {}) {
    return id
      ? await this.$chats.findProjectChat({ id, owner_project_id })
      : null
  }

  getMessageProfiles({ messageMentions, selectedUser, currentUser }) {
    const profiles = messageMentions
      .filter((m) => m.profile)
      .map((m) => m.profile.name)
    if (selectedUser?.name && selectedUser !== currentUser) {
      profiles.push(selectedUser.name)
    }
    return profiles.filter(
      (v, ix, arr) => arr.findIndex((vv) => vv === v) === ix
    )
  }

  getMessageFiles({ messageMentions, files }) {
    return [
      ...messageMentions.filter((m) => m.file).map((m) => m.file),
      ...(files || []),
    ]
  }

  addMessage({ chat, message }) {
    if (chat?.id) {
      this.$storex.chats.addMessageToChat({ chatId: chat.id, message })
    } else {
      chat.messages = [...(chat.messages || []), message]
    }
  }

  removeMessage({ chat, message }) {
    const ix = chat.messages.findIndex((m) => m.doc_id === message.doc_id)
    if (chat.mode === "task" && message.role === "assistant" && ix > 1) {
      chat.messages[ix - 1].hide = false
      if (chat.messages[ix - 2]) chat.messages[ix - 2].hide = false
    }
    chat.messages = chat.messages.filter((_, i) => i !== ix)
  }

  toggleHide({ chat, doc_id }) {
    const msg = chat.messages.find((m) => m.doc_id === doc_id)
    if (msg) msg.hide = !msg.hide
  }

  toggleAnswer({ chat, doc_id }) {
    const msg = chat.messages.find((m) => m.doc_id === doc_id)
    if (msg) msg.is_answer = !msg.is_answer
  }

  hideAll({ chat }) {
    chat.messages.forEach((m) => {
      m.hide = true
    })
  }

  updateExistingMessage({ chat, doc_id, update }) {
    const existing = chat.messages.find((m) => m.doc_id === doc_id)
    if (existing) Object.assign(existing, update)
  }

  removeFileFromMessage({ message, file }) {
    message.files = message.files.filter((f) => f !== file)
  }

  removeFileFromChat({ chat, file }) {
    chat.file_list = chat.file_list?.filter((f) => f !== file)
  }

  addFileToChat({ chat, file }) {
    if (chat.file_list?.includes(file)) return false
    chat.file_list = [...(chat.file_list || []), file]
    return true
  }

  async parseImageFromPaste(e) {
    if (!e.clipboardData?.items) return null
    return (
      [...e.clipboardData.items]
        .find((f) => f.type.indexOf("image") !== -1)
        ?.getAsFile() || null
    )
  }

  async parseTextFromPaste(e) {
    if (!e.clipboardData?.items) return null
    const textItem = [...e.clipboardData.items].find(
      (f) => f.type.indexOf("text") !== -1
    )
    if (!textItem) return null
    return new Promise((ok) => textItem.getAsString(ok))
  }

  extractImageUrlFromHtml(html) {
    if (!html.startsWith("<img")) return null
    const match = /src="([^"]+)/.exec(html)
    return match ? match[1] : null
  }

  async uploadImage({ file }) {
    const formData = new FormData()
    formData.append("file", file)
    const response = await this.$storex.api.images.upload(formData)
    return response.path
  }

  async fileToMessage({ file }) {
    const content = await this.$storex.api.files.read(file)
    const ext = file.split(".").reverse()[0]
    return ["```" + `${ext} ${file}`, content, "```"].join("\n")
  }

  async extractTextFromImage(image) {
    const byteString = atob(image.src.split(",")[1])
    const mimeString = image.src.split(",")[0].split(":")[1].split(";")[0]
    const byteArray = new Uint8Array(byteString.length)
    for (let i = 0; i < byteString.length; i++)
      byteArray[i] = byteString.charCodeAt(i)
    const blob = new Blob([byteArray], { type: mimeString })
    const file = new File([blob], "image", { type: mimeString })
    return this.$api.tools.imageToText(file)
  }

  buildSubTaskPayload({
    title,
    description,
    files,
    profiles,
    mode,
    column,
    projectId,
    parentId,
    board,
    metadata,
    user,
  }) {
    return {
      name: title,
      messages: [
        {
          role: "user",
          content: description,
          images: [],
          profiles: [],
          user: user || this.$user.username,
          meta_data: {},
          done: true,
        },
      ],
      project_id: projectId,
      parent_id: parentId,
      file_list: files || [],
      profiles: profiles || [],
      mode: mode,
      column: column,
      board: board,
      metadata: metadata || {},
      activateChat: false,
    }
  }

  getCaretWordInfo(editor) {
    if (!editor?.innerText) return {}
    const caretIndex = this._getEditorCaretCharOffset(editor)
    const text = editor.innerText
    const lastWorkIndex = text.slice(0, caretIndex).split(/\s/g).length - 1
    const word = text.split(/\s/g)[lastWorkIndex]
    return { caretIndex, lastWorkIndex, word }
  }

  _getEditorCaretCharOffset(element) {
    let caretOffset = 0
    if (window.getSelection) {
      const range = window.getSelection().getRangeAt(0)
      const preCaretRange = range.cloneRange()
      preCaretRange.selectNodeContents(element)
      preCaretRange.setEnd(range.endContainer, range.endOffset)
      caretOffset = preCaretRange.toString().length
    }
    return caretOffset
  }

  startVoiceRecognition({ lang, onResult, onEnd }) {
    const recognition = new (window.SpeechRecognition ||
      window.webkitSpeechRecognition)()
    recognition.lang = lang
    recognition.interimResults = false
    recognition.onresult = onResult
    recognition.onend = onEnd
    recognition.start()
    return recognition
  }

  async syncNotebook({ project, chat }) {
    return this.$storex.chat.syncNotebookToChat({ project, chat })
  }

  async exportNotebook({ project, chat, file }) {
    return this.$storex.chat.exportChatToNotebook({ project, chat, file })
  }

  async saveChat(chat) {
    if (!chat.temp) {
      return await this.$chats.saveChat(chat)
    }
  }

  async sendChatMessage({ chat, storex }) {
    return await storex.projects.chatWihProject(chat)
  }

  async validateFile({ file, parentChat }) {
    const fileChat = file.chat || await this.createFileChat({ file, parentChat })

    if (fileChat.messages.some(m => !m.hide)) {
      fileChat.messages.forEach(m => { m.hide = true })
      await this.saveChat(fileChat)
    }

    const message = this.getUserMessage({
      taskItem: 'review',
      message:
        [
          `Follow profiles instructions to validate the latest changes in the file: ${file.fileFullName}.`,
          "If no profiles are present, create a summary of best practices of the file with example and suggestions of how to improve file quality",
          file.diff ? 'Focus on the last changes from the diff:\n' + file.diff : ''
        ].join("\n"),
      files: [file.fileFullName]
    })

    return this.sendMessage({ chat: fileChat, message })
  }

  async validateAllFiles({ prReviewChat, files }) {
    await Promise.all(
      files.filter((f) => !f.isDeleted).map((file) =>
        this.validateFile({
          file,
          parentChat: prReviewChat,
        })
      )
    )
  }

  async createFileChat({ parentChat, file, project_id, column, message, metadata }) {
    column = column || parentChat.column
    const { fileFullName, fileShortName, profiles } = file
    const payload = this.buildSubTaskPayload({
      title: fileShortName,
      description: message,
      files: [fileFullName],
      profiles: profiles.map(p => p.name),
      mode: 'task',
      column,
      metadata,
      project_id: parentChat.project_id,
      parent_id: parentChat.id,
      board: parentChat.board,
      projectId: project_id || parentChat.project_id,
      parentId: parentChat.id,
      user: this.$user.username
    })
    file.chat = await this.$chats.createNewChat(payload)
    return file.chat
  }

  async newQuickChat({ project } = {}) {
    const selectedProject = project || this.$storex.projects.activeProject
    const chat = {
      name: "Quick chat",
      mode: 'chat',
      auto_initialize: true,
      owner_project_id: selectedProject.project_id
    }
    const quickChat = await this.$chats.createNewChat(chat)
    this.$ui.openChat(quickChat)
  }

  async createChat({
    files,
    name,
    mode = 'chat',
    message,
    profiles = [],
    metadata = {},
    activate = false,
  }) {
    const fileNames = (files || []).map(f => f.split('/').pop())
    const chatName = name ||
      `Files: ${fileNames.slice(0, 2).join(', ')}${fileNames.length > 2 ? ` +${fileNames.length - 2}` : ''}`

    const openingMessage = message ||
      `Working with files:\n${(files || []).map(f => `- ${f}`).join('\n')}`

    const payload = {
      name: chatName,
      mode,
      file_list: files || [],
      profiles,
      metadata,
      auto_initialize: false,
      messages: [
        this.getUserMessage({
          message: openingMessage,
          files: files || [],
          profiles,
          metadata,
        })
      ]
    }

    const chat = await this.$chats.createNewChat(payload)

    if (activate) {
      await this.$chats.setActiveChat(chat)
    }

    return chat
  }

  getChatProject(chat) {
    const projectId = chat?.project_id || chat?.owner_project_id
    if (projectId) {
      return this.$projects.allProjectsById[projectId] || this.$project
    }
    return this.$project
  }

  updateChatBranches({ chat, currentBranch, compareBranch }) {
    if (!chat) return
    chat.meta_data = {
      ...(chat.meta_data || {}),
      current_branch: currentBranch,
      compare_branch: compareBranch
    }
  }

  findChildChatByFile({ chat, childrenChats, file }) {
    const searchNode = (node, visited = new Set()) => {
      if (!node || visited.has(node.id)) return null
      visited.add(node.id)
      if (node.file_list?.includes(file)) return node
      if (node.children && Array.isArray(node.children)) {
        for (const child of node.children) {
          const found = searchNode(child, visited)
          if (found) return found
        }
      }
      return null
    }

    if (childrenChats && Array.isArray(childrenChats)) {
      for (const child of childrenChats) {
        const found = searchNode(child)
        if (found) return found
      }
    }

    if (chat) {
      return searchNode(chat)
    }
    return null
  }

  findChatByFileAndMessage({ chat, file, messageId }) {
    if (!file) return null
    const chats = this.$projects?.allChats || []

    const found = chats.find(c => 
      c.file_list?.includes(file) && 
      (c.message_id === messageId || (messageId && c.metadata?.message_id === messageId))
    )
    if (found) return found

    if (chat) {
      const found = chats.find(c => 
        c.file_list?.includes(file) && 
        (c.parent_id === chat.id || c.metadata?.parent_id === chat.id)
      )
      return found
    }
    return null
  }

  extractCodeBlocksFromMessage(message) {
    return extractCodeBlocks(message?.content || '')
  }

  hasCodeBlocksWithFilePaths(message) {
    return hasCodeBlocksWithPaths(message?.content || '')
  }

}

import { getterTree, mutationTree, actionTree } from 'typed-vuex'
import store, { $storex } from '.'
import { API } from '../api/api'
import { v4 as uuidv4 } from 'uuid'

export const namespaced = true

export const state = () => ({
  chats: {},
  activeChatId: null,
  chatEvents: {},
})

function registerChat(state, chat) {
  if (!chat?.id) {
    console.error('[chats store] Attempted to store a null/invalid chat:', chat)
    return
  }
  state.chats[chat.id] = chat
}

function getChatWorkingProject({ owner_project_id, project_id }) {
  return $storex.projects.allProjectsById[project_id || owner_project_id] ||
            $storex.projects.activeProject
}

function getChatProject({ owner_project_id }) {
  return $storex.projects.allProjectsById[owner_project_id] ||
            $storex.projects.activeProject
}

export const getters = getterTree(state, {
  allChats: state => Object.values(state.chats || {}),
  allTags: state => new Set(Object.values(state.chats || {})?.map(c => c.tags).reduce((a, b) => a.concat(b), []) || []),
  allPRs: state => Object.values(state.chats || {}).filter(c => c.pr_view?.from_branch),
  isChatUpdating: state => (chatId) => {
    return (state.chatEvents[chatId]?.updatingCount || 0) > 0
  },
  activeChat: state => state.activeChatId ? (state.chats[state.activeChatId] || null) : null,
  chatProject: state => ({ project_id, owner_project_id }) => {
    return $storex.projects.allProjectsById[project_id || owner_project_id]
  },
})

export const mutations = mutationTree(state, {
  setActiveChatId(state, chatId) {
    state.activeChatId = chatId || null
  },

  clearActiveChat(state) {
    state.activeChatId = null
  },

  setChatUpdating(state, { chatId, updating }) {
    const current = state.chatEvents[chatId]?.updatingCount || 0
    const prevTimeoutId = state.chatEvents[chatId]?.timeoutId || null

    if (prevTimeoutId) {
      clearTimeout(prevTimeoutId)
    }

    if (!updating) {
      state.chatEvents = {
        ...state.chatEvents,
        [chatId]: {
          ...(state.chatEvents[chatId] || {}),
          updatingCount: 0,
          updatingAt: null,
          timeoutId: null,
        }
      }
    } else {
      const timeoutId = setTimeout(() => {
        $storex.chats.setChatUpdating({ chatId, updating: false })
      }, 10000)

      state.chatEvents = {
        ...state.chatEvents,
        [chatId]: {
          ...(state.chatEvents[chatId] || {}),
          updatingCount: current + 1,
          updatingAt: new Date().toISOString(),
          timeoutId,
        }
      }
    }
  },

  addMessageToChat(state, { chatId, message }) {
    const chat = state.chats[chatId]
    if (!chat) return
    chat.messages = [...(chat.messages || []), message]
  },
})

export const actions = actionTree(
  { state, getters, mutations },
  {
    async init ({ state }) {
    },
    async loadChats({ state }) {
      const chats = await API.chats.list()
      chats.forEach(chat => registerChat(state, chat))
    },
    async saveChat({ state }, chat) {
      await API.chats.save(chat)
      await $storex.chats.loadChat(chat)
    },
    async saveChatInfo(_, chat) {
      await API.chats.saveChatInfo({ ...chat, messages: [] })
      await $storex.chats.loadChat(chat)
    },
    async findProjectChat({ state }, { id, owner_project_id }) {
      const project = $storex.projects.allProjectsById[owner_project_id]
      const chat = state.chats[id]
      if (chat) {
        return chat
      }
      const loadedChat = await project.$api.chats.loadChat({ id, owner_project_id })
      registerChat(state, loadedChat)
      return state.chats[id] || null
    },
    async loadChat({ state }, chat) {
      if (!state.chats[chat.id]) {
        const project = getChatProject(chat)
        const loadedChat = await project.$api.chats.loadChat(chat)
        registerChat(state, loadedChat)
      }
      return state.chats[chat.id]
    },
    async reloadChat({ state }, chat) {
      const project = getChatProject(chat)
      const freshChat = await project.$api.chats.loadChat(chat)
      if (freshChat && state.chats[chat.id]) {
        Object.assign(state.chats[chat.id], freshChat)
      } else {
        registerChat(state, freshChat)
      }
      return state.chats[chat.id]
    },
    async deleteChat({ state }, chat) {
      if (!chat.temp) {
        await API.chats.delete(chat)
      }
      if (state.chats[chat.id]) {
        delete state.chats[chat.id]
      }
      if (state.activeChatId === chat.id) {
        $storex.chats.clearActiveChat()
      }
    },
    async setActiveChat({ state }, activeChat) {
      const { id, project_id, owner_project_id } = activeChat || {}

      if (!id) {
        $storex.chats.clearActiveChat()
        return
      }

      await $storex.chats.reloadChat({ id, project_id, owner_project_id })

      $storex.chats.setActiveChatId(id)

      if (!$storex.ui.isMobile && $storex.ui.viewMode !== 'vibe') {
        $storex.ui.openChat($storex.chats.activeChat)
      }
    },
    async createNewChat({ state }, chat) {
      chat = {
        id: uuidv4(),
        mode: 'chat',
        profiles: [],
        chat_index: 0,
        messages: [],
        auto_initialize: !chat.name,
        owner_project_id: chat.owner_project_id || $storex.projects.activeProject.project_id,
        ...chat
      }
      registerChat(state, chat)
      if (!chat.temp) {
        await $storex.chats.saveChat(chat)
      }
      return state.chats[chat.id]
    },
    async createNewChatFromUrl({ state }, chat) {
      chat = {
        id: uuidv4(),
        mode: 'chat',
        profiles: [],
        chat_index: 0,
        ...chat
      }
      const savedChat = await API.chats.fromUrl(chat)
      registerChat(state, savedChat)
      if (!chat.temp) {
        await $storex.chats.setActiveChat(savedChat)
      }
      return state.chats[savedChat?.id]
    },
    async createNewBoardChat({ state }, { boardTitle, columnTitle, chat }) {
      boardTitle = boardTitle || chat.board
      columnTitle = columnTitle || chat.column
      const newColumn = {
        title: columnTitle,
        chats: []
      }
      if (!$storex.projects.kanban) {
        await $storex.projects.loadKanban()
      }
      if (!$storex.projects.kanban.boards[boardTitle]) {
        $storex.projects.kanban.boards = {
          ...$storex.projects.kanban.boards,
          [boardTitle]: {
            columns: [newColumn]
          }
        }
      }
      let column = $storex.projects.allBoards
                        .find(({ title }) => title === boardTitle).columns.find(({ title }) => title === columnTitle)
      if (!column) {
        column = newColumn
        $storex.projects.kanban.boards[boardTitle].columns.push(column)
      }

      const newChat = await $storex.chats.createNewChat({
        board: boardTitle,
        column: columnTitle,
        ...chat
      })
      await $storex.chats.setActiveChat(newChat)
      column.chats = [...column?.chats || [], newChat.id]
      $storex.projects.saveKanban($storex.projects.kanban)
      return newChat
    },
    async createNewThread(_, { chat, mode, message }) {
      const { files, profiles, doc_id: subtaskMessageId } = message
      const findChild = $storex.chats.allChats.find(c => c.message_id === subtaskMessageId)

      if (!findChild) {
        const boardTitle = chat.board
        const columnTitle = chat.column
        await $storex.chats.createNewBoardChat({
          boardTitle, columnTitle,
          chat: {
            parent: chat,
            name: `${subtaskMessageId} - thread`,
            project_id: chat.project_id,
            parent_id: chat.parent_id,
            message_id: subtaskMessageId,
            file_list: files,
            profiles: profiles,
            mode,
            board: chat.board,
            column: chat.column,
            activateChat: true,
            messages: [{ ...message, doc_id: null }]
          }
        })
      } else {
        await $storex.chats.setActiveChat(findChild)
      }
    },
    async onChatEvent({ state }, { event, data }) {
      const {
        chat: {
          id: chatId,
          owner_project_id
        },
        message,
        event_type,
        type,
        codx_path
      } = data

      if (event_type === 'error') {
        $storex.ui.addNotification({ text: message, type: event_type })
      }

      if (chatId) {
        if (type === 'changed' || !state.chats[chatId]) {
          await $storex.chats.reloadChat({ id: chatId, owner_project_id })
        }
        const chat = state.chats[chatId]
        if (chat && message) {
          const isDone = event_type === 'done'
          const currentMessage = chat.messages.find(m => m.doc_id === message.doc_id)

          if (currentMessage) {
            if (isDone) {
              Object.assign(currentMessage, message)
            } else {
              currentMessage.is_thinking = message.is_thinking
              currentMessage.done = message.done
              currentMessage.meta_data = message.meta_data
              currentMessage.profiles = message.profiles
              if (message.is_thinking) {
                currentMessage.think += message.think
              } else {
                if (isDone) {
                  currentMessage.content = message.content
                } else {
                  currentMessage.content += message.content
                }
              }
              currentMessage.updated_at = new Date().toISOString()
            }
          } else {
            $storex.chats.addMessageToChat({ chatId, message })
          }

          const allMessagesDone = chat.messages.every(m => m.done)
          if (allMessagesDone) {
            $storex.chats.setChatUpdating({ chatId, updating: false })
          } else {
            $storex.chats.setChatUpdating({ chatId, updating: !isDone })
          }
        }
      }
    },
    async readFile({ state }, { chat, file }) {
      const project = getChatWorkingProject(chat)
      return project.$api.files.read(file)
    },
    async writeFile({ state }, { chat, file, content }) {
      const project = getChatWorkingProject(chat)
      return project.$api.files.write(file, content)
    }
  }
)
